arguments.command:
cat > src/list.sh <<'EOF'
#!/bin/bash
# list.sh [--room ROOM] [DATE]: bookings, one per line "DATE START-END ROOM WHO", sorted. src/remind.sh reads this.
set -u
BOOKINGS=${BOOKINGS:-data/bookings.tsv}
usage() { echo "usage: list.sh [--room ROOM] [DATE]" >&2; exit 2; }
room=
if [ "${1:-}" = --room ]; then [ $# -ge 2 ] || usage; room=$2; shift 2; fi
[ $# -le 1 ] || usage
date=${1:-}
if [ -n "$date" ] && ! [[ $date =~ ^[0-9][0-9][0-9][0-9]-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$ ]]; then
  echo "bad date: $date (expected YYYY-MM-DD)" >&2; exit 2
fi
[ -r "$BOOKINGS" ] || { echo "bookings file not found: $BOOKINGS" >&2; exit 2; }
grep -v '^#' "$BOOKINGS" | awk -F'\t' -v d="$date" -v r="$room" 'NF && (d == "" || $2 == d) && (r == "" || $1 == r) { printf "%s %s-%s %s %s\n", $2, $3, $4, $1, $5 }' | sort
EOF
sed -i 's/^`bash src\/list.sh \[日付\]`/X/' README.md
python3 - <<'EOF'
import re
p='README.md'
s=open(p,encoding='utf-8').read()
s=s.replace('`bash src/list.sh [日付]` で一覧を出す。','`bash src/list.sh [--room <部屋>] [日付]` で一覧を出す（`--room` は部屋名の完全一致で絞る）。')
open(p,'w',encoding='utf-8').write(s)
EOF
cat README.md
cat > spec/list_room.spec.sh <<'EOF'
#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-01\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\naoi\t2026-01-02\t12:00\t13:00\tz\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-01)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room with date"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-02)" = '2026-01-02 12:00-13:00 aoi z' ] || { echo "list --room with other date"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh --room aoi | head -1)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room ao)" ] || { echo "list --room matched a prefix"; fail=1; }
err=$(BOOKINGS=$t bash src/list.sh --room 2>&1 >/dev/null); rc=$?
{ [ $rc = 2 ] && [ "$err" = 'usage: list.sh [--room ROOM] [DATE]' ]; } || { echo "list --room without value"; fail=1; }
err=$(BOOKINGS=$t bash src/list.sh 2026/11/10 2>&1 >/dev/null); rc=$?
{ [ $rc = 2 ] && [ "$err" = 'bad date: 2026/11/10 (expected YYYY-MM-DD)' ]; } || { echo "list bad date"; fail=1; }
out=$(BOOKINGS=$t bash src/list.sh 2026/11/10 2>/dev/null); [ -z "$out" ] || { echo "list bad date printed stdout"; fail=1; }
rm -f "$t"; exit $fail
EOF
bash tools/check; echo rc=$?; bash tools/lint; echo rc=$?

